function coinChange(coins: number[], amount: number): number {
  // dp[x] — минимальное число монет для суммы x; Infinity — «набрать нельзя»
  const dp: number[] = new Array(amount + 1).fill(Infinity);
  // Сумма 0 набирается нулём монет
  dp[0] = 0;

  for (let x = 1; x <= amount; x++) {
    for (const coin of coins) {
      // Последняя монета — coin, остаток x - coin должен быть набираем
      if (coin <= x && dp[x - coin] + 1 < dp[x]) {
        dp[x] = dp[x - coin] + 1;
      }
    }
  }

  // Если сумма так и осталась ненабираемой — -1
  return dp[amount] === Infinity ? -1 : dp[amount];
}

// Время: O(amount · k), где k — число номиналов
// Память: O(amount)
